package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamRightsBank1 {
  private const val T = "මානව හිමිකම්, මූලික අයිතිවාසිකම් හා පුරවැසි යුතුකම්"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("මිනිසෙකු ලෙස උපත ලැබීම නිසාම සෑම පුද්ගලයෙකුටම උරුම වන පැහැරගත නොහැකි අයිතිවාසිකම් හඳුන්වන්නේ කුමන නමින්ද?", "මානව හිමිකම්", "ව්‍යාපාරික වරප්‍රසාද", "රාජ්‍ය ප්‍රතිපත්ති", "දේපළ බලපත්‍ර", "ජාතිය, ආගම හෝ තරාතිරම නොතකා සෑම මනුෂ්‍යයෙකුටම උපතින් හිමිවන අයිතීන් මානව හිමිකම් වේ."),
    q("වර්ෂ 1215 දී එංගලන්තයේ ජෝන් රජු විසින් අත්සන් තැබූ මානව හිමිකම් ඉතිහාසයේ ප්‍රමුඛ ලියවිල්ල කුමක්ද?", "මැග්නා කාර්ටා ගිවිසුම", "වියනා ප්‍රඥප්තිය", "ජිනීවා සම්මුතිය", "මාස්ට්‍රිච්ට් ගිවිසුම", "රජුගේ අත්තනෝමතික බලය සීමා කර නීතියට යටත් කළ 1215 මැග්නා කාර්ටා ලියවිල්ල ඓතිහාසික සන්ධිස්ථානයකි."),
    q("1789 ප්‍රංශ විප්ලවයෙන් පසු සම්මත කරන ලද ලෝක ප්‍රකට මානව අයිතිවාසිකම් ලේඛනය කුමක්ද?", "මිනිසාගේ හා පුරවැසියාගේ අයිතිවාසිකම් ප්‍රකාශනය", "ඉංග්‍රීසි අයිතිවාසිකම් පනත", "මොන්ටෙවීඩියෝ සම්මුතිය", "බැන්ඩුං ප්‍රකාශනය", "නිදහස, සමානාත්මතාව හා සහෝදරත්වය ප්‍රකාශ කළ මෙම ප්‍රකාශනය නූතන මානව හිමිකම්වලට මග පෑදීය."),
    q("එක්සත් ජාතීන්ගේ සංවිධානය විසින් විශ්ව මානව හිමිකම් ප්‍රකාශනය (UDHR) සම්මත කරගත් දිනය කුමක්ද?", "1948 දෙසැම්බර් 10", "1945 ඔක්තෝබර් 24", "1966 දෙසැම්බර් 16", "1978 සැප්තැම්බර් 07", "1948 දෙසැම්බර් 10 දින පැරිස් නුවරදී විශ්ව මානව හිමිකම් ප්‍රකාශනය සම්මත කෙරිණි."),
    q("සෑම වසරකම ජාත්‍යන්තර මානව හිමිකම් දිනය සමරනු ලබන්නේ කවදාද?", "දෙසැම්බර් 10", "ඔක්තෝබර් 24", "මාර්තු 08", "නොවැම්බර් 20", "1948 දෙසැම්බර් 10 දින UDHR සම්මත වීම සිහිපත් කිරීමට දෙසැම්බර් 10 දිනය නම් කර ඇත."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයේ ඇතුළත් මුළු වගන්ති සංඛ්‍යාව කීයද?", "වගන්ති 30", "වගන්ති 15", "වගන්ති 54", "වගන්ති 12", "සිවිල්, දේශපාලන, ආර්ථික, සමාජ හා සංස්කෘතික අයිතීන් ආවරණය කරන වගන්ති 30ක් UDHR හි ඇත."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනය සම්පාදනය කිරීමේ කමිටුවේ සභාපතිත්වය දැරූ කාන්තාව කවුද?", "එලිනෝර් රූස්වෙල්ට්", "මාග්‍රට් තැචර්", "සිරිමාවෝ බණ්ඩාරනායක", "මාරි කියුරි", "එක්සත් ජාතීන්ගේ මානව හිමිකම් කොමිසමේ සභාපතිනිය ලෙස එලිනෝර් රූස්වෙල්ට් UDHR කෙටුම්පතට නායකත්වය දුන්නාය."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනය (UDHR) රාජ්‍යයන් කෙරෙහි බලපාන නීතිමය ස්වභාවය කුමක්ද?", "සදාචාරාත්මක ප්‍රතිඥාවකි; සෘජුවම නීතියෙන් බැඳීමක් නොවේ", "ශ්‍රේෂ්ඨාධිකරණ දඬුවම් නියෝගයකි", "වෙළඳ ගිවිසුමකි", "පළාත් පාලන අතුරු ව්‍යවස්ථාවකි", "UDHR යනු සදාචාර ප්‍රමිතියක් වන අතර නීත්‍යානුකූලව බැඳෙන ගිවිසුම් වන්නේ ICCPR හා ICESCR සම්මුතීන්ය."),
    q("සිවිල් හා දේශපාලන අයිතිවාසිකම් පිළිබඳ ජාත්‍යන්තර සම්මුතිය (ICCPR) එක්සත් ජාතීන් සම්මත කළ වර්ෂය කුමක්ද?", "1966", "1948", "1989", "1919", "1966 දෙසැම්බර් 16 දින ICCPR සහ ICESCR යන නීතිමය සම්මුති දෙක සම්මත කරන ලදී."),
    q("ජීවත්වීමේ අයිතිය, භාෂණයේ නිදහස හා ඡන්ද අයිතිය මානව හිමිකම්වල කුමන පරම්පරාවට අයත් වේද?", "පළමු පරම්පරාවේ අයිතිවාසිකම්", "දෙවන පරම්පරාවේ අයිතිවාසිකම්", "තෙවන පරම්පරාවේ අයිතිවාසිකම්", "සිව්වන පරම්පරාවේ අයිතිවාසිකම්", "පුද්ගල නිදහස මුල් කරගත් සිවිල් හා දේශපාලන අයිතීන් පළමු පරම්පරාවේ අයිතිවාසිකම් ලෙස හැඳින්වේ."),
    q("අධ්‍යාපන අයිතිය, සෞඛ්‍ය අයිතිය හා සාධාරණ වැටුප් ලැබීමේ අයිතිය අයත් වන්නේ කුමන පරම්පරාවටද?", "දෙවන පරම්පරාවේ අයිතිවාසිකම්", "පළමු පරම්පරාවේ අයිතිවාසිකම්", "තෙවන පරම්පරාවේ අයිතිවාසිකම්", "රාජකීය පරම්පරාවේ අයිතිවාසිකම්", "ආර්ථික, සමාජ හා සංස්කෘතික අයිතිවාසිකම් (ICESCR) දෙවන පරම්පරාවට අයත් වේ."),
    q("පිරිසිදු පරිසරයක ජීවත්වීමේ අයිතිය, සාමයේ අයිතිය හා සංවර්ධන අයිතිය හැඳින්වෙන්නේ කෙසේද?", "තෙවන පරම්පරාවේ (සාමූහික) අයිතිවාසිකම්", "පළමු පරම්පරාවේ අයිතිවාසිකම්", "ව්‍යාපාරික අයිතිවාසිකම්", "රාජ්‍ය නිලධාරී වරප්‍රසාද", "සමස්ත මානව සමාජයේ සහයෝගීතාව මත රැඳෙන සාමූහික අයිතීන් තෙවන පරම්පරාවේ අයිතීන් වේ."),
    q("මානව හිමිකම් 'අන්සතු කළ නොහැකි' (Inalienable) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පුද්ගලයෙකුගෙන් බලෙන් උදුරා ගැනීමට හෝ පවරා දීමට නොහැකි බව", "විදේශිකයන්ට පමණක් හිමි බව", "මුදලට මිලදී ගත හැකි බව", "වයස අවුරුදු 60න් පසු අවලංගු වන බව", "මානව හිමිකම් පුද්ගලයාගෙන් වෙන් කළ නොහැකි බව අන්සතු කළ නොහැකි බවින් කියැවේ."),
    q("මානව හිමිකම් 'අවිභාජ්‍ය හා අන්තර් සම්බන්ධිත' (Indivisible & Interdependent) වීම යනු කුමක්ද?", "එක් අයිතියක් උල්ලංඝනය වීමෙන් අනෙක් අයිතීන්ටද බලපෑම් ඇති වීම", "සිවිල් අයිතීන් පමණක් වැදගත් වීම", "ආර්ථික අයිතීන් පළමු පන්තියට පමණක් දීම", "රජය කැමති අයිතිවාසිකම් පමණක් පිළිගැනීම", "අධ්‍යාපනය, සෞඛ්‍යය හා භාෂණ නිදහස වැනි සියලු හිමිකම් එකිනෙකට බැඳී පවතී."),
    q("මානව හිමිකම් අතුරින් රටක ආණ්ඩුක්‍රම ව්‍යවස්ථාවෙන් නීතිගත කර අධිකරණයෙන් ආරක්ෂා කළ හැකි අයිතීන් හඳුන්වන්නේ කෙසේද?", "මූලික අයිතිවාසිකම්", "සදාචාරාත්මක අයිතිවාසිකම්", "අන්තර්ජාතික වරප්‍රසාද", "ආගමික චාරිත්‍ර", "ව්‍යවස්ථාවේ III වන පරිච්ඡේදය වැනි ලිඛිත නීතියෙන් පිළිගෙන අධිකරණ බලාත්මක කළ හිමිකම් මූලික අයිතිවාසිකම් වේ."),
    q("1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 'මූලික අයිතිවාසිකම්' ඇතුළත් කර ඇත්තේ කුමන පරිච්ඡේදයේද?", "III වන පරිච්ඡේදය (10–17 වගන්ති)", "I වන පරිච්ඡේදය", "VI වන පරිච්ඡේදය", "XII වන පරිච්ඡේදය", "1978 ව්‍යවස්ථාවේ III වන පරිච්ඡේදයේ 10 සිට 17 දක්වා වගන්තිවල මූලික අයිතිවාසිකම් දක්වා ඇත."),
    q("1978 ව්‍යවස්ථාවේ 10 වන වගන්තියෙන් සෑම පුද්ගලයෙකුටම තහවුරු කර ඇති අයිතිවාසිකම කුමක්ද?", "සිතීමේ, හෘදය සාක්ෂියේ සහ ආගමික නිදහස", "තොරතුරු දැනගැනීමේ අයිතිය", "වෘත්තීය සමිති පිහිටුවීමේ නිදහස", "පාර්ලිමේන්තුවට තරග කිරීමේ අයිතිය", "තමන් කැමති ආගමක් හෝ විශ්වාසයක් දැරීමේ හා වැළඳගැනීමේ පරම නිදහස 10 වන වගන්තියෙන් හිමිවේ."),
    q("1978 ව්‍යවස්ථාවේ 11 වන වගන්තිය මඟින් කිසිදු අවස්ථාවක සීමා නොකරන පරම අයිතිවාසිකම කුමක්ද?", "වධහිංසාවලින් සහ කෲර අමානුෂික සැලකිලිවලින් නිදහස් වීමේ අයිතිය", "සාමකාමීව රැස්වීමේ නිදහස", "භාෂණයේ හා ප්‍රකාශනයේ නිදහස", "වෙළඳ ව්‍යාපාර පවත්වාගෙන යාමේ නිදහස", "හදිසි නීති අවස්ථාවකදී පවා 10 හා 11 වගන්ති කිසිදු ලෙසකින් සීමා කළ නොහැක."),
    q("නීතිය ඉදිරියේ සෑම පුද්ගලයෙකුම සමාන බවත් නීතියේ සමාන ආරක්ෂාව හිමි බවත් දැක්වෙන 1978 ව්‍යවස්ථා වගන්තිය කුමක්ද?", "12(1) වගන්තිය", "10 වගන්තිය", "13(5) වගන්තිය", "14(1) වගන්තිය", "සමානාත්මතාවේ අයිතිවාසිකම ව්‍යවස්ථාවේ 12 වන වගන්තිය යටතේ සුරක්ෂිත කර ඇත."),
    q("වර්ගය, ආගම, භාෂාව, කුලය, ස්ත්‍රී පුරුෂ භාවය හෝ උපන් ස්ථානය මත කිසිදු පුරවැසියෙකුට වෙනස්කම් නොකළ යුතු බව දැක්වෙන වගන්තිය කුමක්ද?", "12(2) වගන්තිය", "11 වගන්තිය", "13(1) වගන්තිය", "17 වගන්තිය", "12(2) වගන්තිය මඟින් රාජ්‍ය හා පරිපාලන කටයුතුවලදී වෙනස්කොට සැලකීම (Non-discrimination) තහනම් කරයි."),
    q("කාන්තාවන්, ළමුන් හා ආබාධිත පුද්ගලයන්ගේ අභිවෘද්ධිය සඳහා රජය විශේෂ නීති සම්පාදනය කිරීමට ඉඩ සලසන වගන්තිය කුමක්ද?", "12(4) වගන්තිය", "10 වගන්තිය", "13(6) වගන්තිය", "15(1) වගන්තිය", "දුර්වල හෝ විශේෂ අවශ්‍යතා ඇති කොටස් නගා සිටුවීමට විශේෂ විධිවිධාන (Affirmative Action) පැනවීමට 12(4) ඉඩ දෙයි."),
    q("නීතියෙන් නියම කළ පටිපාටියට අනුකූලව මිස කිසිදු පුද්ගලයෙකු අත්අඩංගුවට ගැනීම තහනම් කරන වගන්තිය කුමක්ද?", "13(1) වගන්තිය", "10 වගන්තිය", "12(3) වගන්තිය", "14(1)(අ) වගන්තිය", "13(1) වගන්තිය අනුව අත්අඩංගුවට ගැනීමේදී ඊට හේතුව පුද්ගලයාට දැනුම් දිය යුතුය."),
    q("අත්අඩංගුවට ගත් පුද්ගලයෙකු ආසන්නතම සුදුසු අධිකරණය හමුවට ඉදිරිපත් කළ යුතු බව දැක්වෙන වගන්තිය කුමක්ද?", "13(2) වගන්තිය", "11 වගන්තිය", "12(1) වගන්තිය", "14(1)(ඇ) වගන්තිය", "13(2) වගන්තිය මඟින් අත්අඩංගුවට ගත් තැනැත්තා අධිකරණ නියෝගයකින් තොරව දිගටම රඳවා තබාගැනීම වළක්වයි."),
    q("අධිකරණයෙන් වරදකරු බව ඔප්පු වන තුරු සෑම පුද්ගලයෙකුම නිර්දෝෂී ලෙස සැලකිය යුතු බව ප්‍රකාශ කරන වගන්තිය කුමක්ද?", "13(5) වගන්තිය", "10 වගන්තිය", "12(2) වගන්තිය", "14(1)(ඉ) වගන්තිය", "13(5) වගන්තිය නීතියේ මූලික සිද්ධාන්තයක් වන නිර්දෝෂීභාවයේ පූර්ව නිගමනය තහවුරු කරයි."),
    q("යම් ක්‍රියාවක් කළ අවස්ථාවේ එය වරදක් නොවූයේ නම් පසුව පනවන නීතියකින් ඊට දඬුවම් නොකළ යුතු බව දැක්වෙන්නේ කුමන වගන්තියේද?", "13(6) වගන්තිය", "11 වගන්තිය", "12(4) වගන්තිය", "14(1)(ඌ) වගන්තිය", "13(6) වගන්තිය මඟින් අතීතයට බලපාන දණ්ඩන නීති පැනවීම තහනම් කරයි."),
    q("භාෂණයේ හා ප්‍රකාශනයේ නිදහස සහ සාමකාමීව රැස්වීමේ නිදහස ඇතුළත් කර ඇත්තේ කුමන වගන්තිය යටතේද?", "14(1) වගන්තිය", "10 වගන්තිය", "11 වගන්තිය", "13(3) වගන්තිය", "14(1)(අ) මඟින් භාෂණ නිදහසත්, 14(1)(ආ) මඟින් සාමකාමීව රැස්වීමේ නිදහසත් තහවුරු කරයි."),
    q("19 වන ව්‍යවස්ථා සංශෝධනයෙන් මූලික අයිතිවාසිකම් පරිච්ඡේදයට අලුතින්ම එක් කළ 14අ (14A) වගන්තිය කුමක්ද?", "තොරතුරු දැනගැනීමේ අයිතිවාසිකම", "වධහිංසාවෙන් නිදහස් වීමේ අයිතිය", "ආගමික නිදහස", "සමානාත්මතාවේ අයිතිය", "රාජ්‍ය ආයතන සතු තොරතුරු ලබාගැනීමේ අයිතිය 14අ වගන්තියෙන් මූලික අයිතිවාසිකමක් බවට පත් විය."),
    q("1978 ව්‍යවස්ථාවේ 14(1) වගන්තියේ දැක්වෙන මූලික අයිතිවාසිකම් සාමාන්‍යයෙන් හිමිවන්නේ කාටද?", "ශ්‍රී ලංකාවේ පුරවැසියන්ට", "විදේශ සංචාරකයන්ට පමණක්", "විදේශ තානාපතිවරුන්ට පමණක්", "රාජ්‍ය සේවකයන්ට පමණක්", "10–13 වගන්ති සියලු පුද්ගලයන්ට හිමිවුවද 14 හා 14අ වගන්ති විශේෂයෙන් 'සෑම පුරවැසියෙකුටම' හිමිවේ."),
    q("රටේ සෑම පුද්ගලයෙකුටම (පුරවැසියන් නොවන අයටද ඇතුළුව) 1978 ව්‍යවස්ථාවෙන් හිමිවන මූලික අයිතිවාසිකම් මොනවාද?", "10, 11, 12(1), 13(1)-(6) වගන්තිවල අයිතීන්", "14(1)(ඒ) වෘත්තීය අයිතිය", "14(1)(ඈ) වෘත්තීය සමිති අයිතිය", "14අ තොරතුරු දැනගැනීමේ අයිතිය", "ව්‍යවස්ථාවේ 'සෑම තැනැත්තෙකුම' ලෙස සඳහන් වන වගන්ති විදේශිකයන්ට පවා හිමිවේ."),
    q("ජාතික ආරක්ෂාව, මහජන සාමය හා මහජන සෞඛ්‍යය ආරක්ෂා කිරීම සඳහා 14 වන වගන්තියේ නිදහස සීමා කළ හැකි බව දක්වන වගන්තිය කුමක්ද?", "15 වන වගන්තිය", "10 වන වගන්තිය", "11 වන වගන්තිය", "17 වන වගන්තිය", "15 වන වගන්තිය අනුව පොදු යහපත උදෙසා ඇතැම් මූලික අයිතිවාසිකම් නීතිය මඟින් සීමා කළ හැක."),
    q("ශ්‍රී ලංකාවේ විධායක හෝ පරිපාලන ක්‍රියාවකින් මූලික අයිතිවාසිකමක් උල්ලංඝනය වූ විට පෙත්සම් ගොනු කළ හැක්කේ කුමන අධිකරණයටද?", "ශ්‍රේෂ්ඨාධිකරණයට", "මහේස්ත්‍රාත් අධිකරණයට", "දිසා අධිකරණයට", "සමථ මණ්ඩලයට", "17 සහ 126 වන වගන්ති අනුව මූලික අයිතිවාසිකම් පෙත්සම් විභාග කිරීමේ තනි අධිකරණ බලය ශ්‍රේෂ්ඨාධිකරණය සතුය."),
    q("මූලික අයිතිවාසිකමක් උල්ලංඝනය වූ දින සිට ශ්‍රේෂ්ඨාධිකරණයට පෙත්සමක් ඉදිරිපත් කළ යුතු නීතිමය කාල සීමාව කුමක්ද?", "මාස 1ක් ඇතුළත", "වසර 2ක් ඇතුළත", "මාස 6ක් ඇතුළත", "දින 7ක් ඇතුළත", "126(2) වගන්තිය අනුව උල්ලංඝනය වී මාස 1ක් (දින 30ක්) ඇතුළත ශ්‍රේෂ්ඨාධිකරණයට අයදුම් කළ යුතුය."),
    q("1978 ව්‍යවස්ථාව යටතේ මූලික අයිතිවාසිකම් නඩුවකදී පුද්ගලයෙකුට අධිකරණයේ පිහිට පැතිය හැක්කේ කුමන ආයතනවල ක්‍රියාවලට එරෙහිවද?", "විධායක හෝ පරිපාලන (රාජ්‍ය) ආයතනවල ක්‍රියාවලට එරෙහිව", "පෞද්ගලික අසල්වැසියන්ගේ පවුල් ආරවුල්වලට එරෙහිව", "විදේශීය රජයන්ට එරෙහිව", "ව්‍යාපාරික හවුල්කරුවන්ට එරෙහිව", "126 වගන්තිය අනුව මූලික අයිතිවාසිකම් පෙත්සම් ඉදිරිපත් කළ හැක්කේ රාජ්‍ය විධායක හෝ පරිපාලන ක්‍රියාවලට එරෙහිවය."),
    q("ශ්‍රී ලංකා මානව හිමිකම් කොමිෂන් සභාව (HRCSL) පිහිටුවන ලද්දේ කුමන වර්ෂයේ පනතකින්ද?", "1996 අංක 21 දරන පනත", "1978 ව්‍යවස්ථාව", "2016 අංක 12 දරන පනත", "1988 අංක 72 දරන පනත", "මානව හිමිකම් ආරක්ෂා කිරීම හා පැමිණිලි විමර්ශනය සඳහා 1996 අංක 21 දරන පනතින් HRCSL ස්ථාපිත කෙරිණි."),
    q("ශ්‍රී ලංකා මානව හිමිකම් කොමිෂන් සභාවට පුද්ගලයෙකු පැමිණිල්ලක් ඉදිරිපත් කිරීමේ ප්‍රධාන වාසිය කුමක්ද?", "අධිකරණ ගාස්තු නොමැතිව සමථ හා නිර්දේශ මඟින් ඉක්මන් සහනයක් ලැබීම", "පාර්ලිමේන්තු මන්ත්‍රී ධුරයක් ලැබීම", "අපරාධකරුවන්ට සිරදඬුවම් නියම කිරීම", "පනත් කෙටුම්පත් අවලංගු කිරීම", "නීතිඥ ගාස්තු නොමැතිව පැමිණිලි විමර්ශනය කර සහන නිර්දේශ කිරීමට මානව හිමිකම් කොමිසම ක්‍රියා කරයි."),
    q("මූලික අයිතිවාසිකම් උල්ලංඝනයකදී පුද්ගලයෙකු මානව හිමිකම් කොමිසමට පැමිණිලි කළ විට ශ්‍රේෂ්ඨාධිකරණයේ මාස 1 කාල සීමාවට කුමක් වේද?", "කොමිසම පැමිණිල්ල විභාග කරන කාලය මාස 1 සීමාවෙන් අඩු කෙරේ", "පෙත්සම් අයිතිය සදහටම අහෝසි වේ", "වසර 10කින් දිගු වේ", "අභියාචනාධිකරණයට මාරු වේ", "මානව හිමිකම් කොමිසම් පනතේ 13(1) වගන්තිය අනුව කොමිසමේ විභාග කාලය මාස 1 සීමාවේදී බැහැර කෙරේ."),
    q("එක්සත් ජාතීන්ගේ ළමා අයිතිවාසිකම් ප්‍රඥප්තිය (UNCRC) සම්මත කරගත් වර්ෂය කුමක්ද?", "1989", "1948", "1966", "2000", "1989 නොවැම්බර් 20 දින UNCRC සම්මත වූ අතර ශ්‍රී ලංකාව 1991 දී එය අපරානුමත කළේය."),
    q("එක්සත් ජාතීන්ගේ ළමා අයිතිවාසිකම් ප්‍රඥප්තිය අනුව 'ළමයෙකු' ලෙස සැලකෙන්නේ කවුද?", "වයස අවුරුදු 18ට අඩු සෑම පුද්ගලයෙකුම", "වයස අවුරුදු 12ට අඩු අය පමණක්", "පාසල් යන සිසුන් පමණක්", "වයස අවුරුදු 14ට අඩු අය පමණක්", "UNCRC 1 වන වගන්තිය අනුව වයස 18ට අඩු සෑම මනුෂ්‍යයෙකුම ළමයෙකු ලෙස අර්ථ දක්වා ඇත."),
    q("එක්සත් ජාතීන්ගේ ළමා අයිතිවාසිකම් ප්‍රඥප්තියේ ඇතුළත් ප්‍රධාන අයිතිවාසිකම් කාණ්ඩ හතර මොනවාද?", "පැවැත්ම, සංවර්ධනය, ආරක්ෂාව සහ සහභාගීත්වය", "ආහාර, රැකියාව, ඡන්දය සහ දේපළ", "බදු, වෙළඳාම, ආරක්ෂාව සහ විවාහය", "මැතිවරණ, දේශපාලන, හමුදා සහ ව්‍යාපාරික", "Survival, Development, Protection සහ Participation යන කාණ්ඩ හතර යටතේ සියලු ළමා අයිතීන් වර්ග කෙරේ."),
    q("පාසල් විනය කමිටුවකදී හෝ පවුල තුළ තමන්ට අදාළ තීරණ ගැනීමේදී දරුවාගේ අදහස්වලට සවන් දීම අයත් වන ළමා අයිතිවාසිකම් කාණ්ඩය කුමක්ද?", "සහභාගීත්ව අයිතිවාසිකම්", "පැවැත්මේ අයිතිවාසිකම්", "දේපළ අයිතිවාසිකම්", "සිවිල් නඩු අයිතිවාසිකම්", "ළමුන්ට තම අදහස් නිදහසේ ප්‍රකාශ කිරීමට හා තීරණවලට දායක වීමට ඇති ඉඩකඩ සහභාගීත්ව අයිතියයි."),
    q("ළමුන්ට නොමිලේ අධ්‍යාපනය, ක්‍රීඩා හා විවේකය ලැබීම අයත් වන්නේ ළමා අයිතිවාසිකම්වල කුමන කාණ්ඩයටද?", "සංවර්ධන අයිතිවාසිකම්", "පැවැත්මේ අයිතිවාසිකම්", "ආරක්ෂණ අයිතිවාසිකම්", "දේශපාලන අයිතිවාසිකම්", "දරුවාගේ ශාරීරික, මානසික හා බුද්ධිමය වර්ධනයට අවශ්‍ය අධ්‍යාපනය හා ක්‍රීඩා සංවර්ධන අයිතීන් වේ."),
    q("දරුවන් ළමා මෙහෙකාර සේවයෙන්, අපයෝජනයෙන් හා යුදමය කටයුතුවලින් මුදාගැනීම අයත් වන්නේ කුමන කාණ්ඩයටද?", "ආරක්ෂණ අයිතිවාසිකම්", "සහභාගීත්ව අයිතිවාසිකම්", "ආර්ථික බදු අයිතිවාසිකම්", "ව්‍යාපාරික අයිතිවාසිකම්", "හිංසනය, නොසලකා හැරීම හා සූරාකෑමෙන් ළමුන් සුරැකීම ආරක්ෂණ (Protection) අයිතිවාසිකම් යටතට ගැනේ."),
    q("ළමයෙකු උපන් අවස්ථාවේ සිට පෝෂණය, සෞඛ්‍ය සේවා සහ නමක් හා ජාතිකත්වයක් ලැබීම අයත් වන කාණ්ඩය කුමක්ද?", "පැවැත්මේ අයිතිවාසිකම්", "වෘත්තීය අයිතිවාසිකම්", "පළාත් සභා අයිතිවාසිකම්", "තොරතුරු අයිතිවාසිකම්", "දරුවාගේ ජීවිතය රැකගැනීම සඳහා අත්‍යවශ්‍ය සෞඛ්‍ය, ආහාර හා අනන්‍යතා හිමිකම් පැවැත්මේ අයිතීන් වේ."),
    q("ශ්‍රී ලංකාවේ ළමා අපයෝජන වැළැක්වීම සහ ළමුන් ආරක්ෂා කිරීම සඳහා පිහිටුවා ඇති ජාතික ආයතනය කුමක්ද?", "ජාතික ළමා ආරක්ෂක අධිකාරිය (NCPA)", "පාරිභෝගික කටයුතු අධිකාරිය", "මධ්‍යම පරිසර අධිකාරිය", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "1998 අංක 50 දරන පනතින් ජාතික ළමා ආරක්ෂක අධිකාරිය (1929 උපකාරක සේවය) ස්ථාපිත කෙරිණි."),
    q("කාන්තාවන්ට එරෙහි සියලු ආකාරයේ වෙනස්කම් කිරීම් තුරන් කිරීමේ ජාත්‍යන්තර සම්මුතිය කෙටියෙන් හඳුන්වන්නේ කුමන නමින්ද?", "CEDAW සම්මුතිය", "UNESCO ප්‍රඥප්තිය", "SAARC සම්මුතිය", "KYOTO ප්‍රඥප්තිය", "1979 දී සම්මත වූ CEDAW සම්මුතිය ස්ත්‍රී පුරුෂ සමානාත්මතාව හා කාන්තා අයිතීන් තහවුරු කරයි."),
    q("1978 ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ පුරවැසියන්ගේ 'මූලික යුතුකම්' (Fundamental Duties) දක්වා ඇති වගන්තිය කුමක්ද?", "28 වන වගන්තිය", "10 වන වගන්තිය", "3 වන වගන්තිය", "126 වන වගන්තිය", "VI වන පරිච්ඡේදයේ 28 වන වගන්තියේ සෑම පුද්ගලයෙකුගේම මූලික යුතුකම් ලැයිස්තුගත කර ඇත."),
    q("ව්‍යවස්ථාවේ 28 වන වගන්තිය අනුව පුරවැසියන් ඉටු කළ යුතු මූලික යුතුකමක් නොවන්නේ කුමක්ද?", "දේශපාලන ප්‍රචාරණ වියදම් ගෙවීම", "ව්‍යවස්ථාවට හා නීතියට ගරු කිරීම", "පොදු දේපළ ආරක්ෂා කිරීම", "ස්වභාවධර්මය හා සම්පත් රැකගැනීම", "28 වන වගන්තියට ජාතික සමගිය, පරිසරය හා පොදු දේපළ සුරැකීම අයත් වුවද පක්ෂ වියදම් ගෙවීම අයත් නොවේ."),
    q("'අයිතිවාසිකම් සහ යුතුකම් එකම කාසියක දෙපැත්ත වැනිය' යන ප්‍රකාශයෙන් පැහැදිලි වන්නේ කුමක්ද?", "අයිතීන් භුක්ති විඳීමට නම් සෙසු අයගේ අයිතීන් ගරු කරන යුතුකම් ඉටු කළ යුතු බව", "යුතුකම් නොමැතිව අයිතිවාසිකම් වැඩි වන බව", "අයිතිවාසිකම් රජයට පමණක් අයත් බව", "යුතුකම් පාසල් සිසුන්ට පමණක් සීමා වන බව", "මගේ භාෂණ නිදහස රැකෙන්නේ අන් අයගේ ගෞරවයට හානි නොකිරීමේ මගේ යුතුකම ඉටු කිරීමෙනි."),
    q("ශ්‍රී ලංකාවේ ශ්‍රේෂ්ඨාධිකරණය මූලික අයිතිවාසිකම් පෙත්සමක් විභාග කිරීමෙන් පසු ලබාදිය හැකි ප්‍රතිකාරයක් කුමක්ද?", "වන්දි ගෙවීමට හා වරද නිවැරදි කිරීමට නියෝග කිරීම", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "අලුත් අමාත්‍යාංශයක් පිහිටුවීම", "රජයේ අයවැය ප්‍රතික්ෂේප කිරීම", "126(4) වගන්තිය අනුව සාධාරණ හා යුක්තිසහගත යැයි හැඟෙන ඕනෑම නියෝගයක් හෝ වන්දියක් දිය හැක."),
    q("ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ මූලික අයිතිවාසිකම් පිළිබඳ වගන්ති ආරක්ෂා කිරීමට අඩු ආදායම්ලාභීන්ට පිහිට වන ආයතනය කුමක්ද?", "නීති ආධාර කොමිෂන් සභාව", "මුදල් මණ්ඩලය", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "සුරාබදු දෙපාර්තමේන්තුව", "දුප්පත් පුරවැසියන්ට නොමිලේ නීතිඥ සහාය දීමට නීති ආධාර කොමිසම ක්‍රියා කරයි."),
    q("කිසියම් රාජ්‍ය සේවකයෙකු උසස්වීම් ලබාදීමේදී සුදුසුකම් නොසලකා දේශපාලන පක්ෂපාතීත්වය මත වෙනස්කම් කළහොත් උල්ලංඝනය වන්නේ කුමන අයිතියද?", "12(1) හා 12(2) සමානාත්මතාවේ අයිතිවාසිකම", "10 ආගමික නිදහස", "13(6) අතීත නීති තහනම", "14(1)(ඌ) වෘත්තීය අයිතිය", "රාජ්‍ය සේවයේ පත්වීම් හා උසස්වීම්වල අත්තනෝමතික අසාධාරණය 12 වන වගන්තිය යටතේ අභියෝග කළ හැක."),
    q("අපරාධ සැකකරුවෙකුගෙන් පාපොච්චාරණයක් ලබාගැනීම සඳහා පොලිස් අත්අඩංගුවේදී පහරදීම සෘජුවම උල්ලංඝනය කරන්නේ කුමන වගන්තියද?", "11 වන වගන්තිය (වධහිංසාවෙන් නිදහස් වීම)", "14(1)(අ) වගන්තිය", "28 වන වගන්තිය", "14අ වගන්තිය", "කිසිදු සැකකරුවෙකුට කායික හෝ මානසික වධහිංසා පැමිණවීම 11 වන වගන්තියෙන් දැඩිව තහනම් කර ඇත."),
    q("පුද්ගලයෙකුට තමා කැමති නීත්‍යානුකූල රැකියාවක් හෝ ව්‍යාපාරයක් තෝරාගැනීමට හිමි මූලික අයිතිවාසිකම ඇතුළත් වන්නේ කුමන වගන්තියේද?", "14(1)(උ) වගන්තිය", "10 වගන්තිය", "11 වගන්තිය", "13(2) වගන්තිය", "නීත්‍යානුකූල ඕනෑම වෘත්තියක, කර්මාන්තයක හෝ වෙළඳාමක නිරත වීමේ නිදහස 14(1)(උ) වගන්තියෙන් දැක්වේ."),
    q("රට තුළ ඕනෑම ප්‍රදේශයක නිදහසේ ගමන් බිමන් යාමට හා පදිංචිය තෝරාගැනීමට පුරවැසියන්ට ඇති අයිතිය දැක්වෙන්නේ කුමන වගන්තියේද?", "14(1)(ඌ) වගන්තිය", "12(4) වගන්තිය", "13(5) වගන්තිය", "10 වගන්තිය", "ශ්‍රී ලංකාව තුළ සංචරණ නිදහස හා කැමති තැනක පදිංචි වීමේ අයිතිය 14(1)(ඌ) වගන්තියෙන් සුරක්ෂිතය."),
    q("විදේශගතව සිටින ශ්‍රී ලාංකික පුරවැසියෙකුට නැවත ශ්‍රී ලංකාවට පැමිණීමට ඇති මූලික අයිතිවාසිකම තහවුරු කරන වගන්තිය කුමක්ද?", "14(1)(එ) වගන්තිය", "11 වගන්තිය", "12(1) වගන්තිය", "28 වගන්තිය", "14(1)(එ) වගන්තිය අනුව ඕනෑම පුරවැසියෙකුට තම මව්බිමට යළි පැමිණීමේ අයිතිය හිමිවේ."),
    q("භාෂණයේ හා ප්‍රකාශනයේ නිදහස යන්නෙන් අනිවාර්යයෙන්ම ගම්‍ය වන්නේ කුමක්ද?", "අන් අයට අපහාස නොකර හා ජාතික සාමයට හානි නොකර අදහස් පළ කිරීම", "ඕනෑම පුද්ගලයෙකුට බොරු අපහාස ප්‍රචාරය කිරීම", "ජාතිවාදී වෛරය ප්‍රසිද්ධියේ පැතිරවීම", "රාජ්‍ය රහස් හා හමුදා සැලසුම් විකුණා දැමීම", "15(2) හා 15(7) වගන්ති අනුව අපහාස නොවන හා මහජන සාමය රැකෙන ලෙස භාෂණ නිදහස භාවිත කළ යුතුය."),
    q("වෙනස් ආබාධිත තත්ත්වයන් ඇති පුද්ගලයන්ට රාජ්‍ය ගොඩනැගිලි හා ප්‍රවාහනයට ප්‍රවේශ වීමේ පහසුකම් සැලසීමෙන් තහවුරු වන්නේ කුමක්ද?", "සමානාත්මතාව හා වෙනස්කොට නොසැලකීමේ අයිතිය", "දේශපාලන මුක්තිය", "වරප්‍රසාදිත බදු නිදහස", "ආගමික බහුත්වවාදය", "ආබාධිත පුද්ගලයන්ට සෙසු පුරවැසියන් හා සමානව සමාජයට සහභාගී වීමට අවස්ථාව සැලසීම මානව හිමිකමකි."),
    q("ශ්‍රී ලංකාවේ දරුවන්ට පළමු වසරේ සිට අවුරුදු 16 දක්වා පාසල් අධ්‍යාපනය ලබාදීමේ අනිවාර්ය නීතිය ක්‍රියාත්මක වන්නේ කුමන අයිතිය තහවුරු කිරීමටද?", "අධ්‍යාපනය ලැබීමේ අයිතිය", "රැකියාවක් තෝරාගැනීමේ අයිතිය", "ඡන්දය ප්‍රකාශ කිරීමේ අයිතිය", "විදේශ ගමන් බලපත්‍ර අයිතිය", "1997 අනිවාර්ය අධ්‍යාපන රෙගුලාසි (වයස 5-16) ළමා සංවර්ධන අයිතිය තහවුරු කරයි."),
    q("යම් පුරවැසියෙකු රජයේ අසාධාරණ බදු අයකිරීමක් හෝ පානීය ජල දූෂණයක් ගැන ශ්‍රේෂ්ඨාධිකරණයට ඉදිරිපත් කරන 'මහජන සුබසිද්ධි නඩුකරය' (PIL) යනු කුමක්ද?", "පොදු මහජනතාවගේ අයිතිවාසිකම් වෙනුවෙන් පුද්ගලයෙකු හෝ සංවිධානයක් නඩු පැවරීම", "තනි පුද්ගල ව්‍යාපාරික නඩුවක්", "රහස් සමථ මණ්ඩල තීන්දුවක්", "අපරාධ අභියාචනාවක්", "මූලික අයිතිවාසිකම් නඩුවලදී සමස්ත ප්‍රජාව වෙනුවෙන් අධිකරණයට යාමට Public Interest Litigation ඉඩ දෙයි."),
    q("රටේ ව්‍යවස්ථාවේ 27 වන වගන්තියේ සඳහන් 'රාජ්‍ය ප්‍රතිපත්තිය මෙහෙයවන මූලධර්ම' සහ III පරිච්ඡේදයේ 'මූලික අයිතිවාසිකම්' අතර වෙනස කුමක්ද?", "රාජ්‍ය ප්‍රතිපත්ති මූලධර්ම උල්ලංඝනය වූ විට සෘජුව අධිකරණයෙන් බලාත්මක කළ නොහැක", "මූලික අයිතිවාසිකම් කිසිදා අධිකරණයට ගෙන යා නොහැක", "රාජ්‍ය ප්‍රතිපත්ති මූලධර්ම විදේශ රටවලට පමණක් අදාළ වේ", "මූලික අයිතිවාසිකම් රජයට පමණක් අයත් වේ", "29 වන වගන්තිය අනුව 27 වන වගන්තියේ මූලධර්ම සඳහා අධිකරණ බලයෙන් සෘජු නඩු පැවරිය නොහැක."),
    q("පාසල් සිසුවෙකු පන්ති කාමරය පිරිසිදුව තබාගැනීම හා පාසල් පුස්තකාල පොත් ආරක්ෂා කිරීම නියෝජනය කරන්නේ කුමන වගකීමද?", "පොදු දේපළ සුරැකීමේ පුරවැසි යුතුකම", "රජයේ විගණන බලතල", "අධිකරණ ස්වාධීනත්වය", "රාජ්‍ය තාන්ත්‍රික වරප්‍රසාද", "සියලු දෙනාගේ පොදු ප්‍රයෝජනය සඳහා ඇති පාසල් දේපළ රැකීම 28 වන වගන්තියේ යුතුකමකි."),
    q("එක්සත් ජාතීන්ගේ ආර්ථික, සමාජ හා සංස්කෘතික අයිතිවාසිකම් පිළිබඳ සම්මුතිය (ICESCR) ප්‍රධාන වශයෙන් අවධාරණය කරන්නේ මොනවාද?", "සෞඛ්‍ය, අධ්‍යාපන, නිවාස හා සාධාරණ වැටුප් අයිතීන්", "රහස් ඡන්ද හා පක්ෂ ක්‍රමය", "යුද අවි පාලනය", "තානාපති නීති", "සාධාරණ ජීවන තත්ත්වයක් පවත්වාගැනීමට අවශ්‍ය ආර්ථික හා සමාජ අයිතිවාසිකම් ICESCR හි ඇතුළත්ය."),
    q("පෞද්ගලිකත්වයට ඇති අයිතිය (Right to Privacy) මගින් පුද්ගලයෙකුට හිමිවන ආරක්ෂාව කුමක්ද?", "පුද්ගලික තොරතුරු, ලිපි හා නිවස අනවසර මැදිහත්වීම්වලින් ආරක්ෂා වීම", "රජයට බදු ගෙවීමෙන් නිදහස් වීම", "මාර්ග නීති කඩ කිරීමට ඉඩ ලැබීම", "ව්‍යාපාර බලපත්‍ර අවශ්‍ය නොවීම", "UDHR 12 වගන්තිය හා ICCPR 17 වගන්තිය පුද්ගලයාගේ පවුල, නිවස හා ගෞරවයට අනිසි මැදිහත්වීම් වළකයි."),
    q("වයෝවෘද්ධ පුද්ගලයන්ට ගරු කිරීම හා ආබාධිත අයට ප්‍රවාහනයේදී ආසන පරිත්‍යාග කිරීම වැනි ක්‍රියා අයත් වන්නේ කුමන අංශයටද?", "සදාචාරාත්මක අයිතිවාසිකම් හා සමාජ යුතුකම්", "දණ්ඩ නීති සංග්‍රහයේ වරප්‍රසාද", "රාජ්‍ය මූල්‍ය ප්‍රතිපත්ති", "අන්තර්ජාතික වෙළඳ නීති", "නීතියෙන් දඬුවම් නොකළද යහපත් පුරවැසියෙකුගෙන් අපේක්ෂා කරන සමාජ සාරධර්ම හා යුතුකම් මේවාය."),
    q("1978 ව්‍යවස්ථාව අනුව භාෂණයේ නිදහස අවභාවිත කරමින් අධිකරණයට අපහාස කිරීම සීමා කළ හැක්කේ කුමන වගන්තියෙන්ද?", "15(2) වගන්තිය", "10 වගන්තිය", "11 වගන්තිය", "28 වගන්තිය", "15(2) වගන්තිය යටතේ අධිකරණ අපහාසය හා ජාතිවාදී වෛරය පැතිරවීම වැළැක්වීමට භාෂණ නිදහස සීමා කළ හැක."),
    q("රටේ පුරවැසියෙකු තම ව්‍යාපාරික ලාභයෙන් නීත්‍යානුකූලව රජයට ගෙවිය යුතු ආදායම් බදු ගෙවීම වැදගත් වන්නේ ඇයි?", "නිදහස් අධ්‍යාපනය, සෞඛ්‍යය හා පොදු සේවා පවත්වාගැනීමට අරමුදල් සැපයීමට", "රජයේ ඇමතිවරුන්ගේ පෞද්ගලික ගිණුම් පිරවීමට", "විදේශ සමාගම්වලට පරිත්‍යාග කිරීමට", "මැතිවරණ අත්හිටුවීමට", "පුරවැසියන් නියමිත බදු ගෙවීම රාජ්‍ය සුබසාධන හා සංවර්ධන ව්‍යාපෘති පවත්වාගැනීමේ පදනමයි."),
    q("මූලික අයිතිවාසිකමක් උල්ලංඝනය වූ විට තුවාල ලැබූ පුද්ගලයාට අමතරව ඔහු වෙනුවෙන් පෙත්සමක් ඉදිරිපත් කළ හැක්කේ කාටද?", "අධිකරණ රීති යටතේ නීතිඥයෙකුට හෝ සමීප පවුලේ නියෝජිතයෙකුට", "විදේශීය හමුදා නිලධාරියෙකුට පමණක්", "පළාත් සභා ආණ්ඩුකාරවරයාට පමණක්", "මැතිවරණ කොමසාරිස්ට පමණක්", "රඳවා තබාගත් හෝ ආබාධිත වූ වින්දිතයෙකු වෙනුවෙන් ඔහුගේ නීතිඥයාට හෝ ඥාතියෙකුට ශ්‍රේෂ්ඨාධිකරණයට යා හැක."),
    q("වැඩබිමක සේවකයන්ට එකම වැඩට ස්ත්‍රී පුරුෂ භේදයකින් තොරව සමාන වැටුපක් ලැබීම තහවුරු කරන ජාත්‍යන්තර මූලධර්මය කුමක්ද?", "සමාන වැඩට සමාන වැටුප", "ඒකාධිකාරී වෙළඳපොළ", "සීමිත කොන්ත්‍රාත් ක්‍රමය", "ප්‍රභූ වරප්‍රසාදය", "UDHR 23(2) හා ILO සම්මුති මඟින් ස්ත්‍රී පුරුෂ භේදයකින් තොරව සමාන වැටුප් අයිතිය පිළිගෙන ඇත."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයේ 1 වන වගන්තියෙන් ප්‍රකාශ කරන මූලික සත්‍යය කුමක්ද?", "සියලු මනුෂ්‍යයෝ නිදහස්ව, ගරුත්වයෙන් හා අයිතිවාසිකම්වලින් සමානව උපත ලබති", "පාලකයන් උපතින්ම උසස් බව", "ආර්ථික බලය ඇති අයට පමණක් අයිතීන් හිමි බව", "ළමුන්ට අයිතිවාසිකම් නොමැති බව", "මානව ගරුත්වය හා සමානාත්මතාව මුළු මානව හිමිකම් ප්‍රකාශනයේම හරයයි."),
    q("ශ්‍රී ලංකාවේ සියලු පුරවැසියන්ට ආගමක් අදහන්නට මෙන්ම ආගමික ඉගැන්වීම් අනුගමනය කිරීමට හා ප්‍රසිද්ධියේ පිළිපැදීමට ඇති වගන්තිය කුමක්ද?", "14(1)(ඉ) වගන්තිය", "10 වගන්තිය පමණක්", "11 වගන්තිය", "13(1) වගන්තිය", "10 වගන්තිය අභ්‍යන්තර විශ්වාසයත්, 14(1)(ඉ) වගන්තිය ආගම ප්‍රසිද්ධියේ පිළිපැදීමේ හා ඉගැන්වීමේ නිදහසත් රකී."),
    q("1978 ව්‍යවස්ථාවේ 10 වගන්තිය හා 14(1)(ඉ) වගන්තිය අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "10 වගන්තිය කිසිදා සීමා කළ නොහැකි අතර 14(1)(ඉ) වගන්තිය 15(7) යටතේ සීමා කළ හැක", "10 වගන්තිය විදේශිකයන්ට අදාළ නොවේ", "14(1)(ඉ) ආගමික නිදහස ගැන නොවේ", "10 වගන්තිය ආර්ථික අයිතියකි", "සිතීමේ හා හෘදය සාක්ෂියේ නිදහස පරම වන අතර ප්‍රසිද්ධ ආගමික චාරිත්‍ර මහජන සාමය මත සීමා විය හැක."),
    q("ජාතික ආපදා හෝ හදිසි නීති අවස්ථාවකදී පුරවැසියෙකුගෙන් ප්‍රධාන වශයෙන් අපේක්ෂා කරන පුරවැසි යුතුකම කුමක්ද?", "විපතට පත් වූවන්ට සහාය වීම හා රජයේ ආරක්ෂක උපදෙස්වලට අවනත වීම", "අසත්‍ය කටකතා සමාජ මාධ්‍යවල පැතිරවීම", "අත්‍යවශ්‍ය ආහාර සඟවා වැඩි මිලට විකිණීම", "සහන කණ්ඩායම්වලට බාධා කිරීම", "ආපදා අවස්ථාවල සාමූහික වගකීමෙන් හා කරුණාවෙන් ක්‍රියා කිරීම සක්‍රීය පුරවැසිභාවයයි."),
    q("ශ්‍රී ලංකාවේ ළමා හා කාන්තා අපයෝජන සම්බන්ධ පැමිණිලි කඩිනමින් විමර්ශනයට පොලිස් ස්ථානවල පිහිටුවා ඇති ඒකකය කුමක්ද?", "ළමා හා කාන්තා කාර්යාංශය", "රථවාහන කොට්ඨාසය", "විශේෂ විගණන අංශය", "රේගු විමර්ශන ඒකකය", "කාන්තාවන්ට හා දරුවන්ට සිදුවන හිංසන කාරුණිකව හා කඩිනමින් විමර්ශනයට මෙම කාර්යාංශ පිහිටුවා ඇත."),
    q("වැඩබිමක වයස අවුරුදු 16ට අඩු ළමුන් අනතුරුදායක රැකියාවල යෙදවීම තහනම් කර ඇත්තේ කුමන අරමුණින්ද?", "දරුවන්ගේ අධ්‍යාපන අයිතිය, සෞඛ්‍යය හා ආරක්ෂාව තහවුරු කිරීමට", "වැඩිහිටියන්ගේ විශ්‍රාම වයස වැඩි කිරීමට", "කර්මාන්තශාලා සංඛ්‍යාව අඩු කිරීමට", "රජයේ පාසල් වැසීමට", "ළමා ශ්‍රමය සූරාකෑම වැළැක්වීම ජාතික හා ජාත්‍යන්තර ළමා අයිතිවාසිකම් නීතියේ ප්‍රමුඛ අරමුණකි."),
    q("රැකියා ස්ථානයකදී සේවකයෙකුට තම අයිතිවාසිකම් දිනාගැනීමට වෘත්තීය සමිතියක් පිහිටුවා ගැනීමේ හා එයට බැඳීමේ නිදහස ලැබෙන්නේ කුමන වගන්තියෙන්ද?", "14(1)(ඈ) වගන්තිය", "11 වගන්තිය", "12(4) වගන්තිය", "28 වගන්තිය", "1978 ව්‍යවස්ථාවේ 14(1)(ඈ) වගන්තියෙන් සේවකයන්ට වෘත්තීය සමිති නිදහස පිරිනමා ඇත."),
    q("පුරවැසියන්ට තම සංස්කෘතිය භුක්ති විඳීමට හා තම මව් භාෂාව භාවිත කිරීමට හා ප්‍රවර්ධනය කිරීමට ඇති අයිතිවාසිකම දැක්වෙන වගන්තිය කුමක්ද?", "14(1)(ඊ) වගන්තිය", "13(6) වගන්තිය", "10 වගන්තිය", "17 වගන්තිය", "බහුසංස්කෘතික සමාජයක සෑම ජන කොටසකගේම භාෂා හා සංස්කෘතික අනන්‍යතාව 14(1)(ඊ) වගන්තියෙන් රැකදේ."),
    q("පුරවැසියන්ට සංගමයක් හෝ සමාජ සේවා සංවිධානයක් පිහිටුවාගෙන එක්රැස් වීමට ඇති නිදහස හඳුන්වන්නේ කුමන වගන්තියෙන්ද?", "14(1)(ඇ) සමාගමයේ නිදහස", "11 වධහිංසාවෙන් නිදහස", "13(1) අත්අඩංගුවට ගැනීමේ නීතිය", "28 යුතුකම් වගන්තිය", "නීත්‍යානුකූල අරමුණු සඳහා සංවිධාන හා සංගම් පිහිටුවීමේ නිදහස 14(1)(ඇ) වගන්තියෙන් තහවුරු කෙරේ."),
    q("ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ IV වන පරිච්ඡේදය (18–25 වගන්ති) මඟින් ආරක්ෂා කර ඇති පුරවැසි අයිතිවාසිකම් ක්ෂේත්‍රය කුමක්ද?", "භාෂා අයිතිවාසිකම්", "අධිකරණ විනිසුරු වැටුප්", "පළාත් සභා මැතිවරණ", "තානාපති සබඳතා", "සිංහල හා දෙමළ රාජ්‍ය භාෂා ලෙසත් ඉංග්‍රීසි සන්ධාන භාෂාව ලෙසත් භාවිත කිරීමේ අයිතීන් IV පරිච්ඡේදයේ ඇත."),
    q("රටේ පරිපාලන භාෂාව පිළිබඳ 1978 ව්‍යවස්ථාවේ 18 වන වගන්තිය අනුව ශ්‍රී ලංකාවේ රාජ්‍ය භාෂාවන් මොනවාද?", "සිංහල සහ දෙමළ", "සිංහල සහ ඉංග්‍රීසි පමණක්", "සිංහල පමණක්", "ඉංග්‍රීසි පමණක්", "1987 13 වන සංශෝධනයෙන් පසු 18 වන වගන්තිය අනුව සිංහල හා දෙමළ දෙකම රාජ්‍ය භාෂා වේ."),
    q("1978 ව්‍යවස්ථාවේ 18(3) වගන්තිය අනුව ශ්‍රී ලංකාවේ 'සන්ධාන භාෂාව' (Link Language) ලෙස පිළිගෙන ඇත්තේ කුමන භාෂාවද?", "ඉංග්‍රීසි භාෂාව", "ප්‍රංශ භාෂාව", "පාලි භාෂාව", "සංස්කෘත භාෂාව", "සිංහල හා දෙමළ ජන කොටස් අතර අන්‍යෝන්‍ය සන්නිවේදන සන්ධාන භාෂාව ලෙස ඉංග්‍රීසි පිළිගැනේ."),
    q("තම මව් භාෂාවෙන් රාජ්‍ය ආයතන සමඟ ලිපි ගනුදෙනු කිරීමට හා අධ්‍යාපනය ලැබීමට ඇති අයිතිය ආරක්ෂා කිරීම වැදගත් වන්නේ ඇයි?", "ජාතික සංහිඳියාව, ගරුත්වය හා සමාන පුරවැසි අවස්ථා තහවුරු වන බැවිනි", "විදේශ විනිමය ඉතිරි වන බැවිනි", "පාසල් විෂය මාලා අඩු කිරීමට", "මැතිවරණ කොට්ඨාස අඩු කිරීමට", "තමාට හුරුපුරුදු භාෂාවෙන් රජයේ සේවා ලැබීම සමානාත්මතාවේ ප්‍රධාන පියවරකි."),
    q("මානව හිමිකම් ආරක්ෂා කිරීමේදී පාසල් 'මානව හිමිකම් හා සාම කව' මඟින් ඉටුවන කාර්යය කුමක්ද?", "සිසුන් තුළ ඉවසීම, අන්‍යයන්ට ගරු කිරීම හා යුතුකම් පිළිබඳ ආකල්ප වර්ධනය කිරීම", "විභාග ප්‍රශ්න පත්‍ර මුද්‍රණය කිරීම", "විනිසුරුවරුන් පත් කිරීම", "පාසල් බදු අය කිරීම", "ළමා වියේ සිටම අන් අයගේ අයිතීන් හඳුනාගැනීමට හා සාමකාමීව ගැටලු විසඳීමට සිසුන් හුරුකරයි."),
    q("සෑම පුරවැසියෙකුටම 'ස්වභාවික යුක්තිය' (Natural Justice) හිමිවීම යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "අපක්ෂපාතී විනිශ්චයකරු ඉදිරියේ තම නිදහසට කරුණු දැක්වීමට අවස්ථාව ලැබීම", "පැමිණිලි නොමැතිව දඬුවම් නියම කිරීම", "වනාන්තර නීති ක්‍රියාත්මක කිරීම", "මුදල් ඇති අයට පමණක් නඩු දිනවීම", "කිසිවෙකුටත් සවන් නොදී දඬුවම් නොකිරීම (Audi Alteram Partem) ස්වභාවික යුක්තියේ මූලධර්මයකි."),
    q("පුද්ගලයෙකුගේ ජීවිතයට හා සෞඛ්‍යයට තර්ජනයක් වන විෂ අපද්‍රව්‍ය බැහැර කිරීම වැළැක්වීමෙන් රැකෙන්නේ කුමන අයිතිවාසිකමද?", "ජීවත්වීමේ හා පිරිසිදු පරිසරයක සිටීමේ අයිතිය", "රහස් ඡන්ද අයිතිය", "වෘත්තීය සමිති අයිතිය", "තොරතුරු දැනගැනීමේ අයිතිය", "පිරිසිදු ජලය හා වාතය නොමැති වීම ජීවත්වීමේ හා සෞඛ්‍ය අයිතීන්ට සෘජුවම හානි කරයි."),
    q("ශ්‍රී ලංකාවේ අත්අඩංගුවට ගත් සැකකරුවෙකුට තමාට තේරෙන භාෂාවෙන් හේතු දැනගැනීමට හා නීතිඥ සහාය ගැනීමට ඇති අයිතිය කුමක්ද?", "සාධාරණ නඩු විභාගයකට ඇති මූලික අයිතිවාසිකම", "ආර්ථික හා වාණිජ අයිතිවාසිකම", "දේශපාලන මුක්ති අයිතිවාසිකම", "විදේශීය වීසා අයිතිවාසිකම", "13(1) සහ 13(3) වගන්ති මඟින් සැකකරුගේ සාධාරණ ආරක්ෂාව හා නීති සහාය තහවුරු කෙරේ."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයට ඇතුළත් සරණාගත අයිතිවාසිකම (14 වගන්තිය) මඟින් කියැවෙන්නේ කුමක්ද?", "හිංසනයෙන් මිදී වෙනත් රටක ආරක්ෂිත රැකවරණය පැතීමට ඇති අයිතිය", "ඕනෑම රටක රජයේ රැකියා ඉල්ලීමේ අයිතිය", "වෙනත් රටක මැතිවරණ පැවැත්වීමේ අයිතිය", "බදු නොගෙවා ජීවත්වීමේ අයිතිය", "යුද්ධය හෝ දේශපාලන හිංසනය නිසා ජීවිත අවදානමට ලක්වූවන්ට ආරක්ෂාව පැතීම UDHR හි පිළිගෙන ඇත."),
    q("මහජන සෞඛ්‍යයට හා පරිසරයට හානි නොවන පරිදි ප්ලාස්ටික් හා පොලිතීන් භාවිතය අඩු කිරීම පුරවැසියෙකුගේ කවර යුතුකමක්ද?", "ස්වභාවධර්මය හා ස්වභාවික සම්පත් ආරක්ෂා කිරීමේ යුතුකම", "ආගමික පූජා සිදු කිරීමේ යුතුකම", "මැතිවරණ ප්‍රචාරණ යුතුකම", "විදේශ විනිමය ඉපැයීමේ යුතුකම", "28(ඊ) වගන්තිය අනුව පරිසරය ආරක්ෂා කර සංරක්ෂණය කිරීම සෑම පුරවැසියෙකුගේම මූලික යුතුකමකි."),
    q("පෞද්ගලික අංශයේ හෝ රාජ්‍ය අංශයේ රැකියා ස්ථානවල සේවිකාවන්ට හිමිවන ප්‍රසූත නිවාඩු වැනි පහසුකම් තහවුරු කරන්නේ කුමක්ද?", "මාතෘත්වය හා කාන්තා අයිතිවාසිකම් රැකීම", "ව්‍යාපාරික ලාභය උපරිම කිරීම", "සේවකයන් රැකියාවෙන් ඉවත් කිරීම", "විදේශීය වෙළඳ ගිවිසුම්", "UDHR 25(2) සහ CEDAW සම්මුතිය මඟින් මව්වරුන්ට හා දරුවන්ට විශේෂ රැකවරණය හා සහාය හිමිවේ."),
    q("සෑම පුරවැසියෙකුටම තම අදහස් ප්‍රකාශ කිරීමේදී මෙන්ම අන් අයගේ විවේචනවලටද ගරු කිරීමේ ගුණාංගය හඳුන්වන්නේ කෙසේද?", "ඉවසීම සහ ප්‍රජාතන්ත්‍රවාදී සංස්කෘතිය", "අන්තවාදය සහ ඒකාධිපතිත්වය", "විධායක අධිකාරිය", "නිෂේධ බලය", "විවිධ මත ඉවසීමෙන් පිළිගැනීම මානව හිමිකම් රැකෙන සමාජයක අත්‍යවශ්‍ය ගුණාංගයකි."),
    q("නීතිය ඉදිරියේ සමානාත්මතාව රැකීම සඳහා අපරාධයක වින්දිතයන්ට හා සාක්ෂිකරුවන්ට රජය ලබාදිය යුතු ආරක්ෂාව කුමක්ද?", "තර්ජන හා බියගැන්වීම්වලින් තොරව සාක්ෂි දීමට නීතිමය රැකවරණය සැලසීම", "නඩුව ප්‍රසිද්ධියේ විසුරුවා හැරීම", "වින්දිතයන්ට විරුද්ධව දඩ පැනවීම", "සාක්ෂිකරුවන් රටින් පිටුවහල් කිරීම", "2015 අපරාධයක වින්දිතයන් සහ සාක්ෂිකරුවන් ආරක්ෂා කිරීමේ පනතින් මෙම අයිතිය ශක්තිමත් කෙරිණි."),
    q("මානව හිමිකම් පිළිබඳව සලකා බලන විට සෑම අයිතිවාසිකමකටම සීමාවක් පවතින්නේ කවදාද?", "එය තවත් පුද්ගලයෙකුගේ අයිතිවාසිකමකට හෝ පොදු යහපතට බාධා වන තැනදී", "රජයට බදු ආදායම් අවශ්‍ය වූ විට", "විදේශීය සංචාරකයන් පැමිණි විට", "සති අන්තයේ නිවාඩු දිනවලදී", "අන් අයගේ නිදහස හා මහජන සාමය ආරම්භ වන සීමාවෙන් තම අයිතිවාසිකම් භාවිතයේ සීමාව තීරණය වේ."),
    q("ශ්‍රී ලංකාවේ ළමා අයිතිවාසිකම් ආරක්ෂා කිරීම සඳහා පාසල් තුළ ශාරීරික දඬුවම් තහනම් කරමින් චක්‍රලේඛ නිකුත් කර ඇත්තේ ඇයි?", "දරුවන්ගේ කායික හා මානසික ගරුත්වය ආරක්ෂා කර හිංසනය වැළැක්වීමට", "සිසුන් පාසල් යාම නතර කිරීමට", "ගුරුවරුන්ගේ නිවාඩු වැඩි කිරීමට", "පාසල් විභාග අහෝසි කිරීමට", "UNCRC 19 වන වගන්තිය හා 11 වන ව්‍යවස්ථා වගන්තිය අනුව ළමුන්ට ශාරීරික හිංසා කිරීම වැළැක්විය යුතුය."),
    q("පුද්ගලයෙකු මියගිය පසු පවා ඔහුගේ අවමංගල්‍ය කටයුතු ගෞරවනීය ලෙස සිදු කිරීම පිළිබිඹු කරන්නේ කුමක්ද?", "මානව ගරුත්වයට ඇති අන්තිම ගෞරවය", "රාජ්‍ය ආදායම් ප්‍රතිපත්තිය", "මැතිවරණ සමානුපාතිකත්වය", "ව්‍යවස්ථාදායක වරප්‍රසාදය", "සෑම මිනිසෙකුගේම සංස්කෘතික හා ආගමික විශ්වාස අනුව ගෞරවයෙන් අවසන් කටයුතු කිරීම පිළිගැනේ."),
    q("විශ්ව මානව හිමිකම් ප්‍රකාශනයේ 26 වන වගන්තිය මඟින් ලෝකයේ සෑම පුද්ගලයෙකුටම තහවුරු කර ඇති මූලික අයිතිවාසිකම කුමක්ද?", "අධ්‍යාපනය ලැබීමේ අයිතිය", "රහස් ඡන්ද අයිතිය", "රැකියා වර්ජන අයිතිය", "පාර්ලිමේන්තු වරප්‍රසාද", "මූලික හා ප්‍රාථමික අධ්‍යාපනය නොමිලේ හා අනිවාර්ය විය යුතු බව UDHR 26 වගන්තිය ප්‍රකාශ කරයි."),
    q("නූතන සමාජයේ ජනමාධ්‍ය හා සමාජ මාධ්‍ය භාවිතයේදී පුරවැසියෙකු සතු ප්‍රධාන යුතුකමක් කුමක්ද?", "සත්‍ය තොරතුරු බෙදාගැනීම හා අන් අයගේ පෞද්ගලිකත්වයට ගරු කිරීම", "වෛරී ප්‍රකාශ වේගයෙන් ප්‍රචාරය කිරීම", "අනුන්ගේ ඡායාරූප අවසර නොමැතිව විකෘති කිරීම", "අසත්‍ය පුවත් නිර්මාණය කිරීම", "ඩිජිටල් අවකාශයේදීද අන් අයගේ ගෞරවය හා අයිතිවාසිකම් රැකීම සෑම පුරවැසියෙකුගේම වගකීමකි."),
    q("රාජ්‍ය පරිපාලනය තුළ 'සමාන ප්‍රවේශ අයිතිය' (12(3) වගන්තිය) යන්නෙන් පුරවැසියාට හිමිවන්නේ කුමක්ද?", "පොදු ආපනශාලා, හෝටල්, කඩසාප්පු හා පූජනීය ස්ථානවලට ජාති කුල භේදයකින් තොරව පිවිසීමේ අයිතිය", "පෞද්ගලික නිවෙස්වලට බලෙන් ඇතුළු වීමේ අයිතිය", "හමුදා කඳවුරුවලට අවසර නොමැතිව යාමේ අයිතිය", "රජයේ රහස් ලිපි කියවීමේ අයිතිය", "කුලය, ජාතිය හෝ ආගම මත පොදු ස්ථානවලට ඇතුළු වීම වැළැක්වීම 12(3) වගන්තියෙන් තහනම් කර ඇත."),
    q("එක්සත් ජාතීන්ගේ මානව හිමිකම් කවුන්සිලයේ (UNHRC) මූලස්ථානය පිහිටා ඇති නගරය කුමක්ද?", "ජිනීවා", "නිව්යෝර්ක්", "පැරිස්", "ලන්ඩන්", "ස්විට්සර්ලන්තයේ ජිනීවා නුවර එක්සත් ජාතීන්ගේ මානව හිමිකම් කවුන්සිලයේ මූලස්ථානය පිහිටා ඇත."),
    q("සාමකාමී උද්ඝෝෂණයකට සහභාගී වන පුරවැසියන්ට පොලිසියෙන් අනවශ්‍ය ලෙස පහර දීමෙන් උල්ලංඝනය වන්නේ කුමන අයිතිවාසිකම්ද?", "14(1)(ආ) සාමකාමීව රැස්වීමේ අයිතිය හා 11 වධහිංසාවෙන් නිදහස් වීමේ අයිතිය", "18 රාජ්‍ය භාෂා අයිතිය", "28 පොදු දේපළ යුතුකම", "13(6) අතීත නීති අයිතිය", "ආයුධ රහිතව සාමකාමීව රැස්වීමට ඇති නිදහස ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකමකි."),
    q("ශ්‍රී ලංකාවේ ඕනෑම පුරවැසියෙකු තමා ජීවත් වන ගමේ පොදු මාර්ග, වැව් හා වනාන්තර රැකීමට ඉදිරිපත් වීම පෙන්වා දෙන්නේ කුමක්ද?", "සක්‍රීය හා වගකීම්සහගත පුරවැසිභාවය", "රාජ්‍ය පරිපාලන මධ්‍යගතකරණය", "ඒකපාක්ෂික දේශපාලනය", "බහුවිධ ඡන්ද ක්‍රමය", "අයිතිවාසිකම් ඉල්ලා සිටීමට අමතරව ප්‍රජා යහපත වෙනුවෙන් ක්‍රියා කිරීම සක්‍රීය පුරවැසි ගුණාංගයකි."),
    q("පෞද්ගලික අංශයේ වැඩ කරන කම්කරුවන්ට සෞඛ්‍ය ආරක්ෂාව හා ආරක්ෂිත වැඩ පරිසරයක් ලබාදීමේ වගකීම ඇත්තේ කාටද?", "සේවායෝජකයාට සහ නියාමන රාජ්‍ය ආයතනවලට", "පාසල් සංවර්ධන සමිතියට", "පළාත් සභා මන්ත්‍රීවරයාට පමණක්", "අධිකරණ ලේකම්වරයාට", "කම්කරු නීති හා කර්මාන්තශාලා ආඥාපනත යටතේ වැඩබිම් ආරක්ෂාව තහවුරු කිරීම සේවායෝජක වගකීමකි."),
    q("මානව හිමිකම් පිළිබඳව දැනුවත් පුරවැසි සමාජයක් ගොඩනැගීමේදී රාජ්‍ය නොවන සංවිධාන (NGO) ඉටු කරන ධනාත්මක කාර්යය කුමක්ද?", "අයිතිවාසිකම් කඩවීම් අධීක්ෂණය කිරීම හා නීති අධ්‍යාපනය ලබාදීම", "රජයේ මුදල් අච්චු ගැසීම", "අධිකරණ නඩු තීන්දු අවලංගු කිරීම", "මැතිවරණ පැවැත්වීම", "වින්දිතයන්ට හඬක් නැගීමට හා ප්‍රජා දැනුවත් කිරීමට මානව හිමිකම් සංවිධාන සහාය වේ.")
  )
}
